import{NextRequest,NextResponse}from'next/server';import{z}from'zod';import{requireActiveAdmin}from'@/lib/admin-auth';import{createAdminClient}from'@/lib/supabase/admin'
const schema=z.object({toStatus:z.enum(['confirmed','declined','cancelled']),lockVersion:z.number().int().positive()})
export async function POST(r:NextRequest,{params}:{params:Promise<{id:string;assignmentId:string}>}){const a=await requireActiveAdmin();if('response'in a)return a.response;const{id,assignmentId}=await params;let body:unknown;try{body=await r.json()}catch{return NextResponse.json({error:'Invalid JSON'},{status:400})}const p=schema.safeParse(body);if(!p.success)return NextResponse.json({error:'Please check the action'},{status:400});const db=createAdminClient();const{data:x}=await db.from('event_vendor_assignments').select('booking_id').eq('id',assignmentId).maybeSingle();if(!x||x.booking_id!==id)return NextResponse.json({error:'Vendor assignment not found'},{status:404});const{error}=await db.rpc('transition_admin_vendor_assignment',{p_assignment_id:assignmentId,p_to_status:p.data.toStatus,p_expected_lock_version:p.data.lockVersion,p_admin_id:a.admin.id});return error?NextResponse.json({error:error.message},{status:error.code==='40001'?409:400}):NextResponse.json({ok:true})}
